import { appendFile, mkdir, readdir, readFile, stat } from "node:fs/promises";
import { join } from "node:path";

/** Session ids are generated by the client; anything else is refused (no path tricks). */
export const SESSION_ID = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;
const MAX_BODY_BYTES = 1_000_000;

/**
 * Append-only per-session interaction logs (JSONL), one file per session.
 * Used for after-action review and the legibility probe report.
 */
export class SessionStore {
  constructor(readonly dir: string) {}

  /** Append NDJSON lines. Every line must be a JSON object. Returns the number of lines written. */
  async append(id: string, body: string): Promise<number> {
    if (!SESSION_ID.test(id)) throw new SessionError(400, "invalid session id");
    if (Buffer.byteLength(body) > MAX_BODY_BYTES) throw new SessionError(413, "batch too large");
    const lines = body.split("\n").filter((l) => l.trim().length > 0);
    for (const l of lines) {
      let v: unknown;
      try {
        v = JSON.parse(l);
      } catch {
        throw new SessionError(400, "every line must be JSON");
      }
      if (typeof v !== "object" || v === null || Array.isArray(v)) throw new SessionError(400, "every line must be a JSON object");
    }
    if (lines.length === 0) return 0;
    await mkdir(this.dir, { recursive: true });
    await appendFile(join(this.dir, `${id}.jsonl`), lines.join("\n") + "\n", "utf8");
    return lines.length;
  }

  async list(): Promise<{ id: string; bytes: number }[]> {
    let names: string[];
    try {
      names = await readdir(this.dir);
    } catch {
      return [];
    }
    const out: { id: string; bytes: number }[] = [];
    for (const n of names.filter((x) => x.endsWith(".jsonl")).sort()) {
      out.push({ id: n.slice(0, -6), bytes: (await stat(join(this.dir, n))).size });
    }
    return out;
  }

  async read(id: string): Promise<string> {
    if (!SESSION_ID.test(id)) throw new SessionError(400, "invalid session id");
    try {
      return await readFile(join(this.dir, `${id}.jsonl`), "utf8");
    } catch {
      throw new SessionError(404, "no such session");
    }
  }
}

export class SessionError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
  }
}
